<?php require __DIR__.'/config.php';$pageTitle='Contact';$sent=false;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare("INSERT INTO messages(name,email,message) VALUES(?,?,?)");$s->execute([trim($_POST['name']),trim($_POST['email']),trim($_POST['message'])]);$sent=true;}require __DIR__.'/includes/header.php';?><div class="auth"><h1>We're here to help.</h1><?php if($sent): ?><div class="notice">Thanks! Your message has been received.</div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><label>Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Message</label><textarea name="message" rows="5" required></textarea><button class="btn full">Send message</button></form></div><?php require __DIR__.'/includes/footer.php';?>
